<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$type=(string)($_GET['type']??'journal');$format=(string)($_GET['format']??'view');$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-t')));$rows=[];$headers=[];
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$from=finance_step16_date($from,'from date');$to=finance_step16_date($to,'to date');if(!in_array($type,['journal','cashbook','pnl','monthly'],true))$type='journal';
if($type==='journal'){$headers=['Date','Journal','Type','Source','Account','Debit','Credit','Memo'];$stmt=$pdo->prepare("SELECT j.journal_date Date,j.journal_number Journal,j.journal_type Type,COALESCE(j.source_type,'manual') Source,CONCAT(a.account_code,' • ',a.account_name) Account,l.debit_amount Debit,l.credit_amount Credit,COALESCE(l.line_memo,j.memo,'') Memo FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id JOIN finance_ledger_accounts a ON a.id=l.ledger_account_id AND a.organization_id=l.organization_id WHERE l.organization_id=? AND j.journal_date BETWEEN ? AND ? ORDER BY j.journal_date,j.id,l.line_no");$stmt->execute([$orgId,$from,$to]);$rows=$stmt->fetchAll();}
elseif($type==='cashbook'){$headers=['Date','Journal','Account','Source','Inflow','Outflow','Net'];$stmt=$pdo->prepare("SELECT j.journal_date Date,j.journal_number Journal,c.account_name Account,COALESCE(j.source_type,'manual') Source,l.debit_amount Inflow,l.credit_amount Outflow,(l.debit_amount-l.credit_amount) Net FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id JOIN finance_cash_accounts c ON c.id=l.cash_account_id AND c.organization_id=l.organization_id WHERE l.organization_id=? AND l.cash_account_id IS NOT NULL AND j.journal_date BETWEEN ? AND ? ORDER BY j.journal_date,j.id,l.line_no");$stmt->execute([$orgId,$from,$to]);$rows=$stmt->fetchAll();}
elseif($type==='pnl'){$headers=['Class','Code','Account','Debits','Credits','Net'];$p=finance_step16_pnl($pdo,$orgId,$from,$to);foreach($p['rows'] as $r)$rows[]=['Class'=>$r['account_class'],'Code'=>$r['account_code'],'Account'=>$r['account_name'],'Debits'=>$r['debits'],'Credits'=>$r['credits'],'Net'=>$r['net']];}
else{$headers=['Month','Income','Expense','Profit','Cash In','Cash Out','Net Cash'];$stmt=$pdo->prepare("SELECT DATE_FORMAT(j.journal_date,'%Y-%m') Month,SUM(CASE WHEN a.account_class='income' THEN l.credit_amount-l.debit_amount ELSE 0 END) Income,SUM(CASE WHEN a.account_class='expense' THEN l.debit_amount-l.credit_amount ELSE 0 END) Expense,SUM(CASE WHEN a.account_class='income' THEN l.credit_amount-l.debit_amount ELSE 0 END)-SUM(CASE WHEN a.account_class='expense' THEN l.debit_amount-l.credit_amount ELSE 0 END) Profit,SUM(CASE WHEN l.cash_account_id IS NOT NULL THEN l.debit_amount ELSE 0 END) `Cash In`,SUM(CASE WHEN l.cash_account_id IS NOT NULL THEN l.credit_amount ELSE 0 END) `Cash Out`,SUM(CASE WHEN l.cash_account_id IS NOT NULL THEN l.debit_amount-l.credit_amount ELSE 0 END) `Net Cash` FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id JOIN finance_ledger_accounts a ON a.id=l.ledger_account_id AND a.organization_id=l.organization_id WHERE l.organization_id=? AND j.journal_date BETWEEN ? AND ? GROUP BY DATE_FORMAT(j.journal_date,'%Y-%m') ORDER BY Month");$stmt->execute([$orgId,$from,$to]);$rows=$stmt->fetchAll();}
if($format==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="finance-'.$type.'-'.$from.'-'.$to.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,$headers);foreach($rows as $r){$line=[];foreach($headers as $h)$line[]=$r[$h]??'';fputcsv($out,$line);}fclose($out);exit;}}catch(Throwable $e){$error=$e->getMessage();}
function fx_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Finance Export - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.no-print,.os-sidebar,.os-topbar{display:none!important}.os-layout{display:block}.os-main{max-width:none;margin:0;padding:0}}</style></head><body><header class="os-topbar no-print"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Finance Export</small></span></a><div class="os-top-actions"><button class="os-btn" onclick="window.print()">Print / Save PDF</button><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar no-print"><div class="os-nav-label">Export</div><nav class="os-nav"><a href="finance_export.php?type=journal"><i class="dot"></i>Journal</a><a href="finance_export.php?type=cashbook"><i class="dot"></i>Cashbook</a><a href="finance_export.php?type=pnl"><i class="dot"></i>P&amp;L</a><a href="finance_export.php?type=monthly"><i class="dot"></i>Monthly</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16K • ACCOUNTING EXPORT</div><h1><?= fx_h(strtoupper($type)) ?> export</h1><p><?= fx_h($from) ?> → <?= fx_h($to) ?> • <?= count($rows) ?> row(s)</p></section><section class="os-card no-print" style="margin-top:14px"><form method="get" class="pp-form"><label>Dataset<select name="type"><?php foreach(['journal'=>'Journal','cashbook'=>'Cashbook','pnl'=>'P&L','monthly'=>'Monthly Summary'] as $k=>$v):?><option value="<?= $k ?>" <?= $type===$k?'selected':'' ?>><?= fx_h($v) ?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?= fx_h($from) ?>"></label><label>To<input type="date" name="to" value="<?= fx_h($to) ?>"></label><button>Preview</button><a class="os-btn" href="?type=<?= urlencode($type) ?>&from=<?= urlencode($from) ?>&to=<?= urlencode($to) ?>&format=csv">Download CSV</a></form></section><?php if($error):?><div class="pp-alert bad"><strong>Export diagnostic:</strong> <?= fx_h($error) ?></div><?php else:?><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><?php foreach($headers as $h):?><th><?= fx_h($h) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($headers as $h):?><td><?= fx_h($r[$h]??'') ?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?= max(1,count($headers)) ?>">No data in this period.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
